    if(a==='review')return modal('内容检查',`<p>原型演示，未运行审稿模型。</p><div class="checklist"><div class="check-item"><strong>事实与经历</strong><p>模拟材料不能写成“我亲测有效”。</p></div><div class="check-item"><strong>标题承诺</strong><p>步骤应在正文兑现；没有测量不加倍数。</p></div><div class="check-item"><strong>操作与表达</strong><p>保留适用边界，让读者知道下一步怎么做。</p></div></div>${button('返回修改','close',true)}`);
