    if(a==='page'){state.page=Number(b.dataset.page);persist();return render();}if(a==='make-template'){if(d.confirmed!==sig(d))return notify('请先确认当前文字。');d.assets[state.page]={...d.assets[state.page],basis:sig(d),failed:false};d.checked=null;d.manual=null;persist();return render();}if(a==='image-failure'){d.assets[state.page]={...d.assets[state.page],basis:null,failed:true};d.checked=null;d.manual=null;persist();notify('当前页失败，其他页面保留。');return render();}if(a==='native-image')return modal('Codex 配图任务',`<p>实际生成前确认文字、构图和参考图；这里不调用生图工具。</p><p>正式功能需显示真实任务、原图和失败原因。</p>${button('返回模板','close',true)}`);
