  document.addEventListener('input',e=>{const el=e.target,d=draft();if(el.dataset.edit&&d){d[el.dataset.edit]=el.value;d.confirmed=null;d.checked=null;d.manual=null;persist();$('#live-title').textContent=d.title;$('#live-caption').textContent=d.caption;$('#live-body').textContent=d.body;}if(el.id==='wallpaper-mask'){look.mask=Number(el.value);$('#mask-value').textContent=el.value+'%';paint(look);}});
